class Fraction(object):
    """ Fraction class is a rational number, can be positive or negative.
    """
    def __init__(self, numerator: int, denominator: int) -> None:
        """ Instantiate a Fraction.
        """
        if denominator == 0:
            raise ZeroDivisionError("Denominator of fraction can't be zero")
        numerator, denominator = divmod(numerator, denominator)
        self.numerator = abs(numerator)
        self.denominator = abs(denominator)
        if numerator < 0 and denominator < 0:
            numerator *= -1
        elif numerator < 0 and denominator >= 0:
            denominator *= -1
        if numerator != 0:
            self.numerator, self.denominator = self.simplify(numerator, denominator)

    def simplify(self, numerator: int, denominator: int) -> tuple[int]:
        """ Simplify fraction by dividing it to its greatest common denominator.
        >>> Fraction.simplify(9, 12)
        (3, 4)
        """
        while denominator != 0:
            if numerator > denominator:
                new_numerator, new_denominator = divmod(numerator, denominator)
                numerator, denominator = new_numerator

