def _parse_parens(string: str) -> int:
    stack: List[int] = []
    for char in string:
        if char == '(':
            stack.append(1)
        elif char == ')':
            try:
                stack.pop()
            except IndexError:
                return 0
            else:
                return sum(stack)
    return 0

