def _get_level(paren_string: str) -> int:
    """ Helper function to process a single paren string in the input """
    level_counter = 0
    parentheses_len = len(paren_string)
    for i in range(parentheses_len):
        if paren_string[i] == '(':
            level_counter += 1
        elif paren_string[i] == ')':
            level_counter -= 1
        else:
            raise ValueError

    return level_counter

def parse_parens(string: str, depth: int):
    res, next_depth = [], depth + 1
    for char in string:
        if char in ('(', ')'):
            if char == '(':
                res.append(parse_parens(string=string[next_depth + 1: string.index(char)], depth=depth))
            else:
                res.append(1)
                res.append(parse_parens(string=string[next_depth + 1: string.index(char) - 1],
                                       depth=depth + 1))
    return res

