def digit_product(product: int) -> int:
    """
    >>> digit_product(2 * 4 * 6 * 9 * 9)
    12960
    """
    last_result = 1
    i = 1
    while i < product:
        i *= (i+1)

        if not product % i:
            last_result *= i

    return last_result


