def merge(left_nums: List[int], right_nums: List[int]) -> List[int]:
    """Return merged sorted array after joining nondecreasing `left_nums` and `right_nums` sorted arrays

    >>> merge([1, 3, 5, 7], [2, 4, 6, 8])
    [1, 2, 3, 4, 5, 6, 7, 8]
    """

    nums = []
    left_nums_idx = right_nums_idx = 0

    while left_nums_idx < len(left_nums) and right_nums_idx < len(right_nums):
        if left_nums[left_nums_idx] < right_nums[right_nums_idx]:
            nums.append(left_nums[left_nums_idx])
            left_nums_idx += 1
        else:
            nums.append(right_nums[right_nums_idx])
            right_nums_idx += 1
    if left_nums_idx == len(left_nums):
        nums.extend(right_nums[right_nums_idx:])

