    if n == 0 or n == 1:
        return False
    if n == 2:
        return True

    def f(f, f_prime):
        if f > 2 and f % f_prime == 0:
            return False
        else:
            return f <= n

    f_prime = 2
    for i in range(2, n):
        if f(i, f_prime):
            f_prime = f_prime + 1
    return f_prime == n


