def parse_string_of_parens(paren_string: str) -> List[int]:
    """ Input is a nested string that is represented only in single parentheses (' ( ) ). Input is guaranteed to only be
    strings of form '()', '())', '(())', '(())))', ...
    Each string is expected to be a group which represents a single instance of the structure within parentheses
    of one level of nesting or greater. For instance, '(()))' means the innermost is 2 layers of nesting whereas ')))'
    meaning the outermost parentheses means that the nesting is 2 layers.

nested_level_group = {
    ')': 1,
    '(': -1,
}
parent_stack = []  # Use stack to keep track of nested parentheses groups
level_stack = [0]  # A single number as start point, initialize to zero. So this stack always starts with a level
nested_level_output = []
index = 0
while index < len(paren_string):
    c = paren_string[index]
    current_level = level_stack[-1]

    if c in nested_level_group:
        nested_level_group.update({
            c: current_level + nested_level_group[c],
        })
        index += 1
    elif c == '(':
        level_stack.append(current_level)
        index += 1
    elif c == ')':
        level_stack.pop()
        if parent_stack == []:
            depth = current_level
            nested_level_output.append(depth)
        else:
            # Now, depth refers to this nested level while index keeps track of current string location.
            # So when we encounter right parenthesis, we just append current depth.
            depth = current_level + nested_level_output[parent_stack[-1]]
            nested_level_output.append(depth)
        parent_stack.append(len(parent_stack) - 1)

