def median(numbers: List[float]) -> float:
    """For a given list of input numbers, calculate median.
    Median is the number that is in the middle when all the numbers are sorted:
            if length(numbers) is odd, the median is a number at index = mid.
            if length(numbers) is even, the median is the average of two numbers at indices mid - 1, mid, at index = mid:
    >>> median([1.0, 2.0, 3.0, 4.0])
    2.0
    >>> median([-1.0, 1.0, -2.0, 2.0])
    0.0
    """
    return (
        numbers[len(numbers) // 2] if len(numbers) % 2 else (numbers[len(numbers) // 2 - 1] + numbers[len(numbers) // 2]) / 2.0
    )


