def abs_deviation(numbers: List[float], center: float) -> float:
    """ For a given list of input numbers and a centerpoint,
    calculate the absolute difference between each element and
    the centerpoint.
    >>> abs_deviation([1.0, 2.0, 3.0, 4.0], 2.5)
    0.5
    """
    return sum(abs(n - center) for n in numbers) / float(len(numbers))


def mean_of(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate mean (average) of this
    dataset.
    >>> mean_of([1.0, 2.0, 3.0, 4.0])
    2.5
    """
    tot = 0.0
    for n in numbers:
        tot += n
    return tot / len(numbers)


