def separate_paren_groups_2(paren_string: str) -> List[str]:
    """ Do not use regular expression to solve this. Use stacks to separate groups.
    >>> separate_paren_groups_2('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    result, stack = [], []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            stack.pop()
            result.append(''.join(stack))
        else:
            stack.append(char)
    result.append(''.join(stack))
    return result


