def median(numbers: List[float]) -> float:
    """ Given a nonempty list of numbers, calculate and return the median of the
    numbers. The median is the value separating the higher half of a data set from
    the lower half.
    >>> median([3, 1, 2, 4, 5])
    3
    """
    numbers.sort()
